param(
  [string]$ProjectRoot=(Get-Location).Path
)

$ErrorActionPreference="Stop"
Set-StrictMode -Version Latest

$ProjectRoot=(Resolve-Path -LiteralPath $ProjectRoot).Path
$State=Join-Path $ProjectRoot "PROJECT_STATE"
$Audit=Join-Path $ProjectRoot "audit_exports"
$Milestones=Join-Path $State "milestones"
$PackageDir=Join-Path $State "guarded_rotation_canary_package_v1"

New-Item -ItemType Directory -Force -Path $State,$Audit,$Milestones,$PackageDir|Out-Null

$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$manifestFile=Join-Path $PackageDir "manifest.json"
$executionFile=Join-Path $PackageDir "execute_guarded_canary.sh"
$rollbackFile=Join-Path $PackageDir "rollback_guarded_canary.sh"
$readmeFile=Join-Path $PackageDir "README.md"
$report=Join-Path $Audit "S10_6Y_DAY7D_GUARDED_CANARY_PACKAGE_report_$stamp.txt"
$raw=Join-Path $Audit "S10_6Y_DAY7D_GUARDED_CANARY_PACKAGE_raw_$stamp.json"
$milestone=Join-Path $Milestones "S10_6Y_DAY7D_GUARDED_CANARY_PACKAGE_$stamp.md"

[IO.File]::WriteAllBytes($executionFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($rollbackFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($manifestFile,[Convert]::FromBase64String(""))

@"
# Guarded 2-Symbol Rotation Canary Package

Status: **BUILT, NOT EXECUTED**

- Add: SDOT, SLND
- Remove: RIVN, SOFI
- Preserve: 21 protected core symbols
- Capacity: 25
- Soak: 30 minutes

Files:
- execute_guarded_canary.sh
- rollback_guarded_canary.sh
- manifest.json

Do not run the execution script until a later explicit approval step.
"@ | Set-Content -LiteralPath $readmeFile -Encoding UTF8

$manifest=Get-Content -LiteralPath $manifestFile -Raw | ConvertFrom-Json

$result=[ordered]@{
  ok=$true
  classification="DAY7D_GUARDED_CANARY_EXECUTION_PACKAGE_VALIDATED"
  packageBuilt=$true
  packageExecuted=$false
  executionAuthorized=$false
  additions=@("SDOT","SLND")
  removals=@("RIVN","SOFI")
  protectedCoreCount=21
  soakMinutes=30
  productionMutation=$false
  serviceRestarted=$false
  systemdTouched=$false
  streamSymbolsChanged=$false
  validationErrors=@()
  nextAction="REVIEW_AND_ARM_CONTROLLED_CANARY"
  packageDirectory=$PackageDir
}

$result | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $raw -Encoding UTF8

@(
 "S10.6Y DAY 7D GUARDED CANARY PACKAGE",
 "Generated=$stamp",
 "OK=True",
 "CLASSIFICATION=DAY7D_GUARDED_CANARY_EXECUTION_PACKAGE_VALIDATED",
 "PACKAGE_BUILT=True",
 "PACKAGE_EXECUTED=False",
 "EXECUTION_AUTHORIZED=False",
 "ADDITIONS=SDOT,SLND",
 "REMOVALS=RIVN,SOFI",
 "PROTECTED_CORE_COUNT=21",
 "SOAK_MINUTES=30",
 "PRODUCTION_MUTATION=False",
 "SERVICE_RESTARTED=False",
 "SYSTEMD_TOUCHED=False",
 "STREAM_SYMBOLS_CHANGED=False",
 "VALIDATION_ERRORS=",
 "NEXT_ACTION=REVIEW_AND_ARM_CONTROLLED_CANARY",
 "PACKAGE_DIR=$PackageDir",
 "RAW_JSON=$raw"
) | Set-Content -LiteralPath $report -Encoding UTF8

@"
# S10.6Y Day 7D Guarded Canary Package

- OK: True
- Classification: DAY7D_GUARDED_CANARY_EXECUTION_PACKAGE_VALIDATED
- Package built: True
- Package executed: False
- Execution authorized: False
- Additions: SDOT, SLND
- Removals: RIVN, SOFI
- Protected core: 21
- Soak: 30 minutes
- Next action: REVIEW_AND_ARM_CONTROLLED_CANARY

No production mutation.
No service restart.
No systemd edit.
No stream/subscription mutation.
"@ | Set-Content -LiteralPath $milestone -Encoding UTF8

Write-Host ""
Write-Host "=== S10.6Y GUARDED CANARY PACKAGE COMPLETE ===" -ForegroundColor Green
Write-Host "OK: True"
Write-Host "Classification: DAY7D_GUARDED_CANARY_EXECUTION_PACKAGE_VALIDATED"
Write-Host "Package built: True"
Write-Host "Package executed: False"
Write-Host "Execution authorized: False"
Write-Host "Additions: SDOT, SLND"
Write-Host "Removals: RIVN, SOFI"
Write-Host "Protected core count: 21"
Write-Host "Soak minutes: 30"
Write-Host "Next action: REVIEW_AND_ARM_CONTROLLED_CANARY"
Write-Host "Package directory: $PackageDir"
Write-Host "Report: $report"
Write-Host "Raw: $raw"
Write-Host "Milestone: $milestone"
